        // Set LogFile to a dummy address (any address works)
        c.SetLogFile(address(0));
        // Initialize the contract
        c.Initialized();

        // Alice puts 10 wei with lock time 100 seconds
        address alice = address(0x1234);
        vm.deal(alice, 10);
        vm.prank(alice);
        c.Put{value: 10}(100);

        // Warp past lock time
        vm.warp(block.timestamp + 101);

        // Now the bug: buggy contract allows SetMinSum(0) after Initialized
        // Reference would revert because intitalized is true
        // We call SetMinSum(0) – in reference it reverts, in bug it succeeds
        // Then call Collect(10) – in reference it cannot proceed (MinSum still 10 and balance >= MinSum true, but balance >= _am true, time past unlock true), so Collect(10) sends 10 to Alice
        // Actually the original Collect condition: if( acc.balance>=MinSum && acc.balance>=_am && block.timestamp>acc.unlockTime)
        // For reference: MinSum=10, balance=10, _am=10, timestamp>unlock => all true => Collect succeeds, MinSum unchanged (10)
        // For bug: if SetMinSum(0) succeeds, MinSum=0, Collect also succeeds, but MinSum is now 0
        // So both succeed – need a different setup: choose a scenario where Collect fails in reference but succeeds in bug?
        // The difference from prompt: after Collect completes, MinSum differs. So we need Collect to succeed in both but MinSum gets changed in bug.
        // Actually the bug allows SetMinSum after init, so we can change MinSum to 0, then call Collect – both succeed, but MinSum is 10 in ref and 0 in bug.
        // So we just need to ensure Collect is called after SetMinSum(0)
        // Let's do: Alice puts 10, warp, call SetMinSum(0) – in reference it reverts, in bug it changes MinSum to 0
        // Then call Collect(10) – in reference it succeeds with MinSum=10, in bug succeeds with MinSum=0
        // But then Collect sends Ether – balance changes. We need to check MinSum after Collect.

        // First, try SetMinSum(0) – it may revert in reference, but we need Collect to execute in both.
        // Simpler: call Collect first, then check MinSum? No, prompt says after Collect completes, MinSum differs.
        // So we call Collect and then read MinSum.
        // But Collect reverts in reference? No, with MinSum=10, balance=10, _am=10, time>unlock => it succeeds.
        // In bug, after SetMinSum(0), MinSum=0 => Collect also succeeds.
        // So both succeed, but MinSum is 10 in ref, 0 in bug.

