pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy LogFile contract and set it up first
        address logAddr = address(new LogFile());
        c.SetLogFile(logAddr);
        c.Initialized();

        // Alice puts 10 wei with lockTime 0
        address alice = address(0x1111);
        vm.deal(alice, 10 wei);
        vm.prank(alice);
        c.Put{value: 10 wei}(0);

        // Bob calls SetMinSum(10) — in reference this reverts bc Initialized, in bug it succeeds
        address bob = address(0x2222);
        vm.prank(bob);
        c.SetMinSum(10);

        // Alice calls Collect(0) — condition passes (balance >= MinSum, balance >= _am, timestamp > unlockTime)
        vm.warp(block.timestamp + 1);
        vm.prank(alice);
        c.Collect(0);

        // Assert that MinSum remains 10 in reference (SetMinSum reverted) but becomes 0 in bug (SetMinSum succeeded initially)
        assertTrue(c.MinSum() == 10);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

