pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1);

        // Set MinSum to 100
        c.SetMinSum(100);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Alice deposits 200 wei with lockTime 0
        vm.deal(alice, 200);
        vm.prank(alice);
        c.Put{value: 200}(0);

        // Warp past unlockTime (lockTime=0 so already unlocked)
        vm.warp(block.timestamp + 1);

        // In reference: SetMinSum cannot be called again, MinSum stays 100, Collect(100) should succeed
        // In bug: SetMinSum can be called again, so we call it with 0 to make Collect fail
        // To trigger divergence: in bug, call SetMinSum(0) after Initialized (which reference reverts)
        // But we cannot call SetMinSum in reference - it would revert.
        // Instead, we observe that after the same sequence, in reference MinSum is 100, in bug MinSum is 0
        // 
        // Actually, we need divergent behavior on Collect. Let's make Collect revert in bug but succeed in reference.
        // Bug: SetMinSum called with 0 after init -> MinSum=0, so Collect condition acc.balance>=MinSum (200>=0) holds
        // Reference: cannot call SetMinSum again -> MinSum=100, condition holds (200>=100) 
        // So both succeed - not divergent.
        // 
        // To get divergence: make Collect succeed in reference but fail in bug.
        // Call SetMinSum(200) before init in both, then after init call SetMinSum(1000) in bug (reference reverts).
        // Reference MinSum=200, bug MinSum=1000.
        // Alice deposits 200, tries Collect(200). Reference: 200>=200 passes, bug: 200>=1000 fails.

        // Reset
        c = new C();
        alice = address(0x1);

        c.SetMinSum(200);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // In buggy version, we can call SetMinSum again - but our test uses the deployed contract
        // We cannot change which version, we have one deployment.
        // To compare: deploy two instances? No, only one c.
        // 
        // Better: The test runs ONCE. We must write a test that passes on reference and fails on bug.
        // Since we cannot have both, we write the assertion that reference satisfies and bug breaks.
        // The scenario: same calls, but in bug SetMinSum can be changed after init.
        // After Initialized(), call SetMinSum(0). Reference reverts, bug succeeds.
        // Then Alice deposits 1 wei, lockTime=0, warps, tries Collect(1).
        // Reference: MinSum=200, 1>=200 false -> revert. Bug: MinSum=0, 1>=0 true, Collect succeeds.
        // So Collect reverts in reference, succeeds in bug.

        // Actually implement:
        c = new C();
        alice = address(0x1);

        c.SetMinSum(200);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Try to change MinSum after init - reference reverts, bug succeeds
        // We capture revert boolean
        bool setMinSumSucceeded = false;
        try c.SetMinSum(0) {
            setMinSumSucceeded = true;
        } catch {
            setMinSumSucceeded = false;
        }

        // Alice deposits 1 wei
        vm.deal(alice, 1);
        vm.prank(alice);
        c.Put{value: 1}(0);

        vm.warp(block.timestamp + 1);

        bool collectSucceeded = false;
        try c.Collect(1) {
            collectSucceeded = true;
        } catch {
            collectSucceeded = false;
        }

        // In reference: SetMinSum reverts (MinSum stays 200), Collect reverts (1<200)
        // In bug: SetMinSum succeeds (MinSum=0), Collect succeeds (1>=0)
        // So in reference: setMinSumSucceeded==false && collectSucceeded==false
        // In bug: setMinSumSucceeded==true && collectSucceeded==true
        // Assert that in reference, both are false.
        assertTrue(!setMinSumSucceeded && !collectSucceeded);
    }
}

