contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 100
        c.SetMinSum(100);
        // Initialize the contract (locks SetMinSum in reference)
        c.Initialized();
        // Give address A 1 ether
        address alice = address(0xABCD);
        vm.deal(alice, 1 ether);
        // Alice calls Put with 200 wei and lockTime 0
        vm.prank(alice);
        c.Put{value: 200}(0);
        // Buggy version can call SetMinSum again to lower MinSum to 1
        // Reference will revert because initialized already true
        // We call SetMinSum(1) – it will succeed in buggy, fail in reference
        // But we need a way to observe the divergence after Collect.
        // Observation: In the bug, SetMinSum(1) succeeds, then Collect(200) can succeed (balance=200 >= 1), after which MinSum is still 1.
        // In reference, SetMinSum(1) reverts (initialized guard), so MinSum remains 100, then Collect(200) will revert because MinSum=100 and balance=200 >=100 but lockTime > block.timestamp? 
        // Actually lockTime=0, block.timestamp > 0? Yes, so Collect would succeed in reference too unless we warp time.
        // Instead: keep MinSum=100, warp so that Collect fails? Simpler: Observe that after SetMinSum(1) call returns normally in bug but reverts in ref, we can see divergence by reading MinSum afterwards.
        // But Collect call is not needed: the difference already appears after SetMinSum call: reference reverts so MinSum unchanged (100), bug goes through so MinSum becomes 1.
        // However the problem statement requires driving through Collect. Let's do: bug version SetsetMinSum(1), then calls Collect(200) which succeeds (since balance>=1) and emits log; reference SetMinSum(1) reverts so it never reaches Collect. 
        // We can wrap SetMinSum in try/catch to determine if it reverted.
        bool setOk;
        try c.SetMinSum(1) {
            setOk = true;
        } catch {
            setOk = false;
        }
        // If setOk is true (bug), then proceed to call Collect
        if (setOk) {
            vm.prank(alice);
            c.Collect(200);
        }
        // Now check MinSum: reference should still be 100, bug should be 1
        assertTrue(c.MinSum() == 1 || c.MinSum() == 100, "MinSum differs");
        // Actually we want exactly that reference passes (MinSum == 100) and bug fails (MinSum == 1)
        assertTrue(c.MinSum() == 100, "MinSum should be 100 in reference");
    }
}

